{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "The closest high-transfer analogue, SCH23390, showed rapid brain uptake and striatal accumulation by PET in cynomolgus monkeys, directly demonstrating CNS access for the same benzazepine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "In healthy humans, 11C-SCH23390 rapidly transferred into the brain with 1.2% of injected radioactivity present at 4.5 min, confirming meaningful CNS access in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A para-iodophenyl analogue of SCH23390 showed good rat brain uptake after iv injection (2.27% dose/whole brain at 2 min), supporting CNS access for lipophilic para-substituted benzazepines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A meta-iodophenyl analogue showed good initial brain uptake in rats (1.59% dose/organ at 2 min), indicating ease of BBB passage for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "123I-SCH23982, another close analogue, showed brain uptake in human SPECT within 10 min, supporting transferable CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In rats, the brain-to-blood ratio of 123I-SCH23982 was about 1.2 at 10 min, indicating active brain uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "The only impermeable analogue, [11C]-2-OH-NPA, is a hydrophilic catechol (cLogD 0.77) with low similarity; its failure does not transfer to the lipophilic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass. Direct PET/SPECT and biodistribution data for close SCH23390-like benzazepines show robust CNS access across species; the query shares the same brain-penetrant scaffold and is more lipophilic, while the only impermeable analogue is a hydrophilic distant catechol.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule",
    "No P-gp/BCRP transporter assay for the bromo-dihydrobenzofuran analogue",
    "No human data for the exact query"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

